import hashlib
import math

class BloomFilter:
    """
    A Bloom filter implementation that utilizes a custom bit array 
    and hashing approach without external libraries. The design calculates 
    the size of the bit array and the number of hash functions based 
    on the expected item count and desired false positive rate 
    using the principles of probabilistic data structures.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_number_of_hashes(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        return math.ceil(- (n * math.log(p)) / (math.log(2) ** 2))

    def _optimal_number_of_hashes(self, m: int, n: int) -> int:
        return math.ceil((m / n) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        hash_result = hashlib.sha256(f"{seed}{item}".encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        for i in range(self.hash_count):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True
